BEGIN READ ONLY;
SELECT jsonb_build_object('jobs',(SELECT jsonb_agg(jsonb_build_object('job_id',j.id,'source_key',s.source_key,'status',j.status,'job_state',j.job_state,'trigger_type',j.trigger_type,'queued_at',j.queued_at,'started_at',j.started_at,'finished_at',j.finished_at,'raw_count',j.raw_count,'new_count',j.new_count,'update_count',j.update_count,'unchanged_count',j.unchanged_count,'records_received',j.records_received,'records_parsed',j.records_parsed,'unique_records',j.unique_records) ORDER BY j.id DESC) FROM (SELECT * FROM source_sync_jobs ORDER BY id DESC LIMIT 15) j JOIN sources s ON s.id=j.source_id), 'observations_after_previous_capture',(SELECT jsonb_agg(jsonb_build_object('source_key',s.source_key,'count',n,'first_seen_min',tmin,'first_seen_max',tmax) ORDER BY s.source_key) FROM (SELECT so.source_id,count(*) n,min(ob.first_seen_at) tmin,max(ob.first_seen_at) tmax FROM source_observations ob JOIN source_opportunities so ON so.id=ob.source_opportunity_id WHERE ob.first_seen_at > TIMESTAMPTZ '2026-11-11 09:28:03+00' GROUP BY so.source_id) x JOIN sources s ON s.id=x.source_id), 'active_sync_jobs',(SELECT count(*) FROM source_sync_jobs WHERE status IN ('QUEUED','PENDING','RUNNING','RETRYING')) )::text;
COMMIT;